      L1: "因此脱离了智者欢喜的道路，这圆满教法核心的最胜教授，我看清之后便阐释这大车轨之道，所以我心中充满勇猛欢喜。",
      L2: "那些未被偏袒执着的黑暗所覆盖、具有辨别善恶的精妙智慧、想让这难得的人身不白白浪费的人们，请各位具善者专心努力听讲。",
      L3: "这里总括摄受了一切佛语的精要，全面包含龙猛、无着两大车轨的道统，是通向一切种智地位的胜士典范；",
      L4: "三种士夫的一切行持、所有次第，无所缺失。通过菩提道次第之门，引导具善者趋向佛陀境界，这就是",
      L5: "这里所要阐述的一切法义。",
      L6: "这里传下来的讲授仪式有两种。殊胜的那兰陀寺诸位智者，许可用三种清净门来诠释正法，即轨范语清净、",
      L7: "学者相续清净、所说法清净。后来在止迦摩啰室啰寺，圣教盛行，那里的智者们则认为三种初要：即",
      L8: "造论者的殊胜、正法的殊胜、以及如何讲授与听闻该法的规理。现在这里，应当按照后一种方式来解释。",
      L9: "因此，菩提道次第的引导分为四个部分：一是为显示法源清净而开示造论者的殊胜；二是为使人对教授起敬重而开示",
