      L4: "幼子吉祥藏，出家为比丘，名精进月。次子月藏，便是如今的至尊上师（阿底峡尊者）。”",
      L5: "尊者获得功德的情形分为二部分：一、因知见广博而获得教法功德的情形；二、因如理修行而获得证悟功德的情形。现在讲第一部分。",
      L6: "正如《八十赞》中所说：“二十一岁之中，尊者已精通六十四种技艺、一切工巧，善于构思言辞，并通晓一切量论。”意思是说，在二",
