      L8: "所说：尊者十五岁时，仅仅听闻过一遍《正理滴论》，便与一位机敏善辩的外道论师展开辩论，令对方折服认输，美名由此传遍四方。",
      L9: "此后，尊者在黑山道场，依止瑜伽自在、亲见欢喜金刚本尊圣容、并获金刚空行佛母授记的上师罗睺",
