      L3: "受《大毗婆沙论》，对根本四部的教典极为精通。对于各部派之间受食等种种细微规矩，哪些相互舍弃、哪些相互取用，都能周遍了知而毫不混杂。",
      L4: "由此，尊者已度越自宗与他宗各部派的宗义大海而抵达彼岸，所以是一位无误了解一切教正法中枢要关键的大德。",
      L5: "获得证悟功德的情形：总的来说，佛陀的一切教法圣教都摄于三藏之宝中，因此证法圣教也必须摄入戒、定、慧三学之宝中。其中",
      L6: "戒学，经论中一再赞叹它是定学、慧学等一切功德的所依之处。所以首先必须具足以戒学为主的各种证德。这",
