      L5: "者，修持密法并守护誓戒，我恭敬礼拜。”由于尊者成就了观自身即是本尊的生起次第，以及金刚心的圆满次第三摩地，所以总赞",
      L6: "他为瑜伽士中的尊者；又特别赞叹他如理守护三昧耶，从不越过规范。又如赞中说：“由于具足正念与正知，不作意于非戒之事，谨慎正念",
