      L11: "三年或六年中，修持明禁行。那时他远远听到飞行国中诸空行母的歌唱声，心中还能记忆受持其中的部分内容。",
      L12: "成就慧学中，共通的慧学，是指获得止观双运的毗钵舍那三摩地。不共的慧学，是指获得圆满次第的殊胜三摩",
