      L4: "近边地狱：那八大地狱，每一个都各有四面墙和四扇门，外面都有铁城围绕，铁城也各有",
      L5: "四扇门，每一扇门外，又有其余四种有情地狱。即煨坑；尸粪臭泥，或称秽粪泥，恶臭如同腐尸；利刀道等；无极",
      L6: "大河。其中第一种，是指有热灰火坑，深可没膝，那些有情为了寻求住处，游行到这里，下脚的时候，皮肉以及鲜血都",
      L7: "销烂了，抬脚的时候，皮肉等又重新长出来。第二种，是指与此紧相邻接的一个秽粪坑，臭如死尸，那些有情为了",
      L8: "寻求住处，游行到这里，跌陷其中，头和脚都被淹没。那粪泥之中有许多虫，名叫“利策”，会穿透皮肤进入肌肉，断筋破骨，",
      L9: "吸取骨髓而食。第三种，是指与这粪泥紧相邻接的地方，有许多锋利的刀，刀刃朝上铺成道路，那些有情为了寻求住处，游行到这里。",
      L10: "下脚的时候，皮、肉、筋、血都被刺截；抬脚的时候，又恢复如初。与此紧相邻接的，是剑叶林，那些有情为了寻求住",
