      L12: "倒地，于是有许多黑斑狗前来，撕扯他们的脊背和肋骨而啖食。与此紧相邻接的，是铁设拉末梨树林，那些有情为了寻求住处，游行",
      L13: "（“摣掣”原文为“摣制”）",
