      L2: "拉末梨树林紧相邻接的，有一条宽广的大河，名叫“无极”，其中充满了沸热的灰水。那些有情为了寻求住处，堕入河中被煎煮，",
      L3: "上下漂浮沉没，就像把豆子等放入大锅中，注满了水，用猛火煎煮一样。河的两岸有诸狱卒，手持棍杖、绳索以及大",
      L4: "网，排列而住，遮拦不让他们出来。或者用绳索套住，或者用网捞起，将他们仰放在炽燃的大铁地上，问他们想要什么。他们如果回答说：“我",
