      L2: "这说明那里是黑暗的。《弟子书》中也说：“无比的严寒侵入骨髓，全身战栗而蜷缩，身上起了百个寒疱，破裂后生出许多",
      L3: "虫子，嚼咬抓挠，脂髓脓水淋漓滴落。寒冷逼迫，牙齿打战，毛发竖立，眼睛、耳朵、喉咙等都被寒冷所逼迫，身心之间极为蒙昧，住在寒冷地狱的痛苦最",
