      L9: "比丘，二十个寒疱地狱的寿量，就是一个疱裂地狱的寿量。广说乃至，诸比丘，二十个裂如红莲地狱的寿量，就是一个裂如大",
      L10: "红莲地狱的寿量。”意思是说，要在这么长的寿量中领受痛苦。",
