      L4: "说：“造恶的人在呼吸未断的间隔里，听闻了地狱无量的痛苦，竟然还能像金刚一样毫无畏惧。仅仅是看到地狱的画像、",
      L5: "听闻描述、忆念、读诵或看到地狱的造像，尚且能引发极大的恐怖，何况是亲身去感受那些强烈的异熟果报呢？”在生死的痛苦中，恶趣的痛苦最难忍",
      L6: "受，其中又以地狱的痛苦最为惨烈。在人间，如果一天之内被三百支尖矛不停地猛烈刺入，这种痛苦与地狱中",
      L7: "最轻微的一点痛苦相比，都完全无法相提并论。而在地狱中，又以无间地狱的痛苦最为极致。《亲友书》说：“就像在一切安乐中，灭尽贪爱后的境界是",
      L8: "安乐之王一样；在一切痛苦中，无间地狱的痛苦也最为粗暴猛烈。人间每天用三百支矛极猛烈地贯穿身体所产生的痛苦，比起地狱里哪怕最轻",
      L9: "微的苦，连千万分之一都比不上。”能感召这种种痛苦的因，唯有我们自己内在身语意三门的恶行。知道这些后，应当竭尽全力",
      L10: "去努力，哪怕是轻微的恶行，也不要让它染污身心。正如前书所说：“这些不善果报的种子，就是身语意的各种恶行。你应当竭尽全力地",
      L11: "去策励自己，纵然是像尘埃那么微小的恶行，也不要让它侵入。”",
