      L3: "被杀死；没有自由，被他人驱使，被脚踢、手打、鞭抽、钩刺以及棒打。”其中第一首偈颂显示总的痛苦，第二首偈颂显示个别的痛苦。“鞭打",
      L4: "等”中的“等”字，包括驱驰以及穿鼻等，这是指由人或非人所施加的杀害等。“互相吞啖”，是指在畜生类的同类之中所",
      L5: "造成的损害。“寂灭净善”，是指能证得涅槃的善法；远离了它，显示极为愚蒙，不堪为修道之器。从“脚踢”到“棒",
      L6: "打”而被驱使的五件事，依次是马、水牛、驴、象、牛等。这些都是如《亲友书释》中所说的。此外还有生在黑",
      L7: "暗之处以及水中，老死于那里；背负重物而疲劳，被用来耕地、剪毛，被强迫驱使；又以种种杀害的方法，使它们在苦恼中被杀；又遭受",
