      L2: "道呢？是为了证悟法性。所以诸菩萨发起这样数百种难行。”并引用经证而好好地成立。前面岂不是破除了一切法有",
      L3: "自性吗？我们难道没有多次宣说诸法如果不是由内心安立其自性而有，就连微尘许也没有吗？对于这样的自性，即使是法性、胜",
      L4: "义谛也没有少许，何况其余的法呢？《明显句论》中说：“三世无错乱、不是由新造作的火的本性，这不是先前没有后来新",
