      L10: "是这样，就应当承许中观宗不能获得解脱了。因为获得涅槃的人现证涅槃，又说涅槃就是灭谛，又说它是胜义谛。",
      L11: "如果没有胜义谛，获得涅槃时就必须现证胜义的灭谛，《六十正理论释》中以多方努力好好地成立了这一点。由此，眼等",
      L12: "有为法，在自性之体上是不可以有的；在以法性所立的自性中，也不可以有，所以无论随于哪一种自性都不能成立。真实的胜义谛，",
      L13: "虽然在法性所立的自性中可以是有的，然而立这种自性为非新作以及不依待他，在自性之体上也没有少许，所以也唯是",
