      L2: "都不能成立。所以对于以法性所立的自性，为了见到那种本性而修习诸道，所修的梵行就不是空无意义的。又说毕竟不承许诸",
      L3: "法有自性之体，与现在忽然承许有自性，二者并不相违。《入中论释》中说：“奇怪啊！错误啊！如果已经不承许少许实事，",
