      L5: "趣，是说眼等缘起的本性，是愚稚凡夫所能执取的；如果那就是那些法的自性，那么那自性就是颠倒的，为了证悟它而修习",
      L6: "梵行，就空无意义了。由于那并不就是自性，所以为了见到自性而修习清净梵行，就有意义利益。这又是我观待世俗谛，",
      L7: "说不是新作以及不依待他。如果那本性不是愚夫所见的，以这个作为自性也是合乎正理的。仅仅因为这个缘故，胜义既不是有事，也不是无",
