      L2: "远离无明翳障的圣者的境界，就立这个本性为那些法的自性。”又说：“诸事的无生自性，这又二者都不是，因为唯属于无事、",
      L3: "无体性的缘故，并不在诸事的自性中有。”又有人承许胜义谛，不是在所断的二我戏论上安立的，而是在能证",
