      L5: "障，这摄尽一切障，灭尽这些就得解脱。”意思是烦恼障与所知障二障，这种所破之事在所知中是有的；如果这些没有，一切",
      L6: "有情就应当不需要用功就得到解脱了。理所破，《回诤论》中说：“又有人对于化现的女子，生起是真实女子的邪执，以化身来破",
