      L2: "不合正理。“过违自许”中的“亦”字，显示不仅仅支分的积聚为车子不合理。又承许形状为车子，是分散支分的形状呢，还是支分积聚的形状呢？",
      L3: "如果是分散支分的形状，与先前未相合时的形状，是没有不同的形状呢，还是不同于先前而有另外的形状呢？如果是前者，有过失说：“就像你的各个支分先前有的形状，",
      L4: "立为车子时的形状也是那样；就像支分分散时不称为车子，同样相合时车子也没有。”这是说先前未相合时与后来相合时，车轮等的形状",
      L5: "完全没有差别。就像分散时车子没有一样，同样相合时也应当没有车子。如果后来相合时与先前未相合时车轮等支分的形状，有另外不同的",
      L6: "形状而立为车子，也有过失。如说：“如果现在成为车子时，车轮等有不同的形状，应当可以取到，然而没有，所以唯是形状不是车子。”意思是前",
      L7: "后时间，如果车轮、车轴等有另外不同的形状，按理应当可以得到，然而无论怎样观察终究不可得，所以与先前形状不同的后来形状为车子是不合正理的。如果",
      L8: "各个支分的形状不承许为车子，而以诸支分合聚的总体形状立为车子，也有过失。如说：“因为你的积聚没有实体，形状应当不是支分",
      L9: "积聚的；如果依于不真实的法，这里哪里会有形状呢？”这是说依于支分积聚的形状称为车子是不合理的，因为积聚不是实有的；依于假有的支分积聚施设形状",
