      L2: "又破除依于八种实尘而假立瓶子等，又破除依于实有色等的形状差别而假立瓶子等，因为色等尘自性无",
      L3: "生，它们没有自性，所以实有是不合理的。如《入中论》中说：“由于那些色等这样安住，觉知为瓶子等是不合理的；因为自性无生，所以色等",
      L4: "没有，形状为瓶子等也不合理。”如果说：瓶子如果像车子一样，不是自己支分的合集形状，那么大腹等应当不是瓶子的相，因为那是形状。",
      L5: "回答：如果法有大腹、长颈等相，就承许它为瓶子，而不是大腹等形状为瓶子。如果不是这样，按理也应当承许腹、颈就是瓶子了。",
      L6: "第二，对此断除诤难：诸实事师对此诘难说：如果以观察有无自性的正理，如前面所说以七门寻求车子，由于",
      L7: "它没有所得，按理应当没有车子，那么诸世间就应当没有施设车子名称之处了；然而这是不合理的，现在可以看到说“车子来了”、“买车子”、“把车子拿走”等，",
      L8: "所以有车子等。《入中论释》中回答说，那过失唯有实事师才有，以及自宗没有。第一种，是说世间名言说“车子来了”等，如果像",
