      L11: "所得的，车子应当不存在。诸实事师所设的征难，现在自许讲解中观的人，说中观宗承许有这个诘难。如果承许这样，",
      L12: "必定犯一切名言建立都没有的过失。第二，自宗没有过失，如说：“无论在实性或世间中，虽然以七相都不能成立，如果",
