      L4: "丝线一样，你实在可笑。如说：“如果那时车子尚且没有，因为有支分者没有，支分也就没有。”如果没有有支分者，也就没有支分。如果这样",
      L5: "想：那是不合理的，车子虽然散坏了，车轮等支分的积聚仍然可以得到。然而这不是这样，唯有先看见车子，才执着车轮等是车子的车轮，其余的则",
      L6: "不这样执着。就像车子坏的时候，车轮等与车子完全没有关系，不是车子的支分；所以没有有支分的车子，就没有车子的支分。那时那车子的支分",
      L7: "以及有支分者，二者都没有；然而那车轮等，观待自己的支分，可以称为有支分者，其余的部分为支分，所以没有有支分者就不能立支分。又没有有支分者",
      L8: "也就没有支分的意义，如说：“譬如烧毁车子，就没有支分；以智慧之火烧毁有支分者，也就没有支分。”像这个譬喻，应当了知。",
      L9: "第三，由名称差别都能成立：《入中论释》中解释说：“这一宗不但由世间共许假立车子之名而显然成立，就是",
      L10: "这些名称的差别，由不加观察的世间共许，也应当受许。”如说：“就是这个有支分者以及有分者，众生说车子是作者，",
      L11: "众生又承许它是受者。”这是说车子观待车轮等诸支分、诸部分，共同承许称为有支分者、有分者；同样观待车轮等所取的",
      L12: "事物，称为作者；观待所受的，称为受者。自部中有人说唯承许诸支分、诸部分的合集，离开它们之外没有有支分者、有分者，因为不可",
